const MAX_PAYLOAD_BYTES = 90000;
const MAX_MAIL_CHARS = 40000;
const MAX_CONTEXT_CHARS = 4000;
const KI_MARKIERUNG = /KI-Entwurf \(automatisch erstellt\)|Interne Hinweise zum KI-Entwurf/;
const SELBST_ADRESSEN = ['info@edv-kretzer.de', 'noreply@support-tech.pkr-lab.de'];

function vonMirSelbst(adresse) {
  return SELBST_ADRESSEN.some((a) => String(adresse || '').toLowerCase().includes(a));
}

function stripHtml(html) {
  return String(html || '')
    .replace(/<br\s*\/?>/gi, '\n')
    .replace(/<\/(p|div|li|tr)>/gi, '\n')
    .replace(/<[^>]+>/g, ' ')
    .replace(/&nbsp;/g, ' ')
    .replace(/&lt;/g, '<')
    .replace(/&gt;/g, '>')
    .replace(/&quot;/g, '"')
    .replace(/&#39;/g, "'")
    .replace(/&amp;/g, '&')
    .replace(/[ \t]+/g, ' ')
    .replace(/ ?\n ?/g, '\n')
    .replace(/\n{3,}/g, '\n\n')
    .trim();
}

function textOf(article) {
  return /html/i.test(article.content_type || '') ? stripHtml(article.body) : String(article.body || '').trim();
}

function dateOf(article) {
  return String(article.created_at || '').replace('T', ' ').slice(0, 16);
}

const ergebnis = [];

$input.all().forEach((item, index) => {
  const { articles, ...ticket } = item.json;
  const all = (articles || [])
    .filter((a) => a.sender !== 'System')
    .sort((a, b) => String(a.created_at).localeCompare(String(b.created_at)) || a.id - b.id);

  const oeffentlich = all.filter((a) => !a.internal);

  const erste = oeffentlich[0];
  if (erste && vonMirSelbst(erste.from)) {
    console.log(`Ticket #${ticket.number}: von mir selbst erstellt (${erste.from}), übersprungen`);
    return;
  }

  const letzte = oeffentlich[oeffentlich.length - 1];
  if (letzte && letzte.sender === 'Agent') {
    console.log(`Ticket #${ticket.number}: Team hat bereits geantwortet, übersprungen`);
    return;
  }

  if ([3, 6].includes(ticket.state_id) && !oeffentlich.some((a) => a.sender === 'Agent')) {
    console.log(`Ticket #${ticket.number}: wartet auf Erinnerung oder Schließen, Kunde hat nicht geantwortet, übersprungen`);
    return;
  }

  const context = all
    .filter((a) => a.internal && /^\s*Kontext:/i.test(textOf(a)))
    .map((a) => textOf(a).replace(/^\s*Kontext:\s*/i, ''))
    .join('\n\n')
    .slice(0, MAX_CONTEXT_CHARS);

  const mails = all.filter((a) => !a.internal && textOf(a));
  const lastCustomer = [...mails].reverse().find((a) => a.sender === 'Customer');
  const target = lastCustomer || mails[mails.length - 1];
  if (!target) {
    console.log(`Ticket #${ticket.number}: keine E-Mail zum Beantworten gefunden, übersprungen`);
    return;
  }

  if (all.some((a) => a.internal && a.id > target.id && KI_MARKIERUNG.test(textOf(a)))) {
    console.log(`Ticket #${ticket.number}: KI-Entwurf liegt bereits vor, übersprungen`);
    return;
  }

  const history = mails
    .filter((a) => a.id !== target.id)
    .map((a) => ({ from: a.from || 'unbekannt', date: dateOf(a), text: textOf(a) }));

  const payload = {
    context,
    history,
    mail: {
      from: target.from || 'unbekannt',
      date: dateOf(target),
      subject: target.subject || ticket.title,
      text: textOf(target).slice(0, MAX_MAIL_CHARS),
    },
  };

  let preTrimmed = 0;
  while (Buffer.byteLength(JSON.stringify(payload), 'utf8') > MAX_PAYLOAD_BYTES && payload.history.length > 0) {
    payload.history.shift();
    preTrimmed += 1;
  }
  if (preTrimmed > 0) {
    console.log(`Ticket #${ticket.number}: ${preTrimmed} ältere Mail(s) vor dem Aufruf gekürzt (Payload-Limit ${MAX_PAYLOAD_BYTES} Byte)`);
  }

  ergebnis.push({
    json: {
      ticket,
      modus: 'entwurf',
      replyTo: target.reply_to || target.from || '',
      messageId: target.message_id || '',
      payloadB64: Buffer.from(JSON.stringify(payload), 'utf8').toString('base64'),
      historyCount: payload.history.length,
      preTrimmed,
    },
    pairedItem: { item: index },
  });
});

return ergebnis;

const eingabe = $('LLM-Eingabe bauen').item.json;
const ticket = eingabe.ticket;

let parsed = null;
try {
  parsed = JSON.parse(String($json.stdout || '').trim().split('\n').pop());
} catch (err) {
  parsed = null;
}

if (!parsed || !parsed.ok) {
  const detail = parsed && parsed.error
    ? `${parsed.error.code}: ${parsed.error.message}`
    : String($json.stderr || $json.error || 'keine Ausgabe von ollama-pc/cli.js').trim();
  throw new Error(`Ollama-Anfrage fehlgeschlagen (Ticket #${ticket.number}): ${detail}`);
}

const hinweise = [];
const entwurf = String(parsed.reply || '')
  .replace(/[ \t]*\[INTERN:\s*([^\]]*)\]/g, (_, hinweis) => {
    hinweise.push(hinweis.trim());
    return '';
  })
  .replace(/[ \t]+$/gm, '')
  .replace(/(https?:\/\/\S+) ([.,;:!?])/g, '$1$2')
  .replace(/([^.])\.\.(?!\.)/g, '$1.')
  .replace(/\n{3,}/g, '\n\n')
  .trim();

const kurslinkHinweise = Array.from(entwurf.matchAll(/\[KURSLINK:\s*([^\]]*)\]/g)).map((m) => m[1].trim());

const escapeHtml = (t) => t.replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const entwurfHtml = entwurf
  .replace(/\r\n?/g, '\n')
  .split(/\n{2,}/)
  .map((absatz) => '<p>' + escapeHtml(absatz)
    .replace(/(https?:\/\/[^\s<]*[^\s<.,;:!?])/g, '<a href="$1">$1</a>')
    .replace(/\n/g, '<br>') + '</p>')
  .join('');
const abstand = '<p><br></p><p><br></p>';
const notizHtml = entwurfHtml + abstand + '<p><i>KI-Entwurf (automatisch erstellt)</i></p>';
const hinweiseHtml = hinweise.length
  ? '<p><b>Interne Hinweise zum KI-Entwurf</b></p><ul>' + hinweise.map((h) => '<li>' + escapeHtml(h) + '</li>').join('') + '</ul>'
  : '';

return { json: { ticket, modus: eingabe.modus, replyTo: eingabe.replyTo, messageId: eingabe.messageId, entwurf, entwurfHtml: entwurfHtml + abstand, notizHtml, hinweise, hinweiseHtml, kurslinkHinweise, kurslinkHinweiseB64: Buffer.from(JSON.stringify(kurslinkHinweise)).toString('base64'), warnings: parsed.warnings, stats: parsed.stats } };

const basis = $('Antwortentwurf extrahieren').item.json;
const escapeHtml = (t) => String(t).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');
const KURSLINK_TAG = /\[KURSLINK:\s*([^\]]*)\]/g;

let parsed = null;
if (basis.kurslinkHinweise.length > 0) {
  try {
    parsed = JSON.parse(String($json.stdout || '').trim().split('\n').pop());
  } catch (err) {
    parsed = null;
  }
}

function istAnstehend(meldeschluss, now) {
  const m = /^(\d{2})\.(\d{2})\.(\d{2}|\d{4})$/.exec(String(meldeschluss || '').trim());
  if (!m) return false;
  const jahr = m[3].length === 2 ? 2000 + Number(m[3]) : Number(m[3]);
  return new Date(jahr, Number(m[2]) - 1, Number(m[1])) >= now;
}

const now = new Date();
const auditZeilen = [];
const decisions = basis.kurslinkHinweise.map((hint, idx) => {
  const result = parsed && parsed.ok ? parsed.results[idx] : null;
  if (!result) {
    auditZeilen.push(`Kurslink-Nachschlag fehlgeschlagen für „${escapeHtml(hint)}“`);
    const fallback = `[BITTE PRÜFEN: Upload-Link für ${escapeHtml(hint)}]`;
    return { html: fallback, plain: fallback };
  }
  const anstehend = result.matches.filter((m) => istAnstehend(m.meldeschluss, now));
  if (anstehend.length !== 1) {
    auditZeilen.push(`Kurslink nicht eindeutig: ${escapeHtml(result.kursart || hint)} (${result.matches.length} Treffer gesamt, ${anstehend.length} anstehend) – bitte im Entwurf prüfen`);
    const fallback = `[BITTE PRÜFEN: Upload-Link für ${escapeHtml(result.kursart || hint)}]`;
    return { html: fallback, plain: fallback };
  }
  const treffer = anstehend[0];
  auditZeilen.push(`Kurslink automatisch eingefügt: ${escapeHtml(treffer.kursart)} ${escapeHtml(treffer.code)} (Meldeschluss ${escapeHtml(treffer.meldeschluss)})`);
  const link = escapeHtml(treffer.url);
  return { html: `<a href="${link}">${link}</a>`, plain: treffer.url };
});

function einfuegen(text, isHtml) {
  if (!decisions.length) return text;
  let i = 0;
  return text.replace(KURSLINK_TAG, () => {
    const d = decisions[i];
    i += 1;
    return isHtml ? d.html : d.plain;
  });
}

const entwurf = einfuegen(basis.entwurf, false);
const entwurfHtml = einfuegen(basis.entwurfHtml, true);
const notizHtml = einfuegen(basis.notizHtml, true);
const hinweiseHtml = basis.hinweiseHtml + (auditZeilen.length
  ? '<p><b>Kurslink-Automatik</b></p><ul>' + auditZeilen.map((z) => '<li>' + z + '</li>').join('') + '</ul>'
  : '');

return { json: { ...basis, entwurf, entwurfHtml, notizHtml, hinweiseHtml } };

const MAIL_AN = 'peter.kretzer@dlrg.org';
const MAIL_VON = 'n8n@pkr-service.de';
const ID_ZEILE = 'ID-IT-xi8klGKdh8';
const SCHRIFT = "-apple-system,'Segoe UI',Roboto,Helvetica,Arial,sans-serif";
const FARBEN = { rot: '#c8102e', amber: '#b45309', gruen: '#15803d', blau: '#1d4ed8', grau: '#475569', indigo: '#4338ca' };
const mitId = (text) => String(text).replace(/\s+$/, '') + '\n\n' + ID_ZEILE;
const esc = (s) => String(s ?? '').replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');
const verlinken = (s) => esc(s).replace(/(https?:\/\/[^\s<]*[^\s<.,;:!?)])/g, '<a href="$1" style="color:#1d4ed8;text-decoration:underline">$1</a>');
const absaetze = (text) => String(text).replace(/\r\n?/g, '\n').split(/\n{2,}/).filter((b) => b.trim()).map((b) => '<p style="margin:0 0 14px 0;line-height:1.6">' + verlinken(b.trim()).replace(/\n/g, '<br>') + '</p>').join('');
const felder = (zeilen) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-collapse:collapse;margin:0 0 18px 0;border:1px solid #e5e7eb">' + zeilen.map(([k, v], i) => '<tr style="background:' + (i % 2 ? '#ffffff' : '#f9fafb') + '"><td valign="top" style="padding:9px 12px;width:34%;font-size:13px;color:#6b7280;border-bottom:1px solid #eef0f3">' + esc(k) + '</td><td valign="top" style="padding:9px 12px;font-size:14px;color:#111827;border-bottom:1px solid #eef0f3">' + verlinken(v) + '</td></tr>').join('') + '</table>';
const box = (inhalt, farbe, titel) => '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="margin:0 0 18px 0"><tr><td style="border-left:4px solid ' + farbe + ';background:#f9fafb;padding:14px 16px">' + (titel ? '<div style="font-size:12px;font-weight:700;letter-spacing:.06em;text-transform:uppercase;color:' + farbe + ';margin-bottom:8px">' + esc(titel) + '</div>' : '') + inhalt + '</td></tr></table>';
const liste = (eintraege) => '<ul style="margin:0;padding:0 0 0 18px;line-height:1.6">' + eintraege.map((e) => '<li style="margin:0 0 4px 0">' + verlinken(e) + '</li>').join('') + '</ul>';
const knopf = (text, url, farbe) => '<table role="presentation" cellpadding="0" cellspacing="0" style="margin:4px 0 18px 0"><tr><td style="background:' + farbe + ';border-radius:6px"><a href="' + esc(url) + '" style="display:inline-block;padding:11px 20px;font-size:14px;font-weight:600;color:#ffffff;text-decoration:none">' + esc(text) + '</a></td></tr></table>';
const klein = (text) => '<p style="margin:6px 0 14px 0;font-size:13px;line-height:1.5;color:#6b7280">' + verlinken(text).replace(/\n/g, '<br>') + '</p>';
const datum = (iso, kurz) => {
  const d = new Date(iso);
  return Number.isNaN(d.getTime()) ? String(iso) : d.toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: kurz ? 'short' : 'medium' }) + ' Uhr';
};
const layout = ({ label, farbe, titel, badge, vorschau, abschnitte }) => {
  const zeit = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', dateStyle: 'medium', timeStyle: 'short' });
  const plakette = badge ? '<div style="margin-top:12px"><span style="display:inline-block;background:#ffffff;color:' + farbe + ';font-size:12px;font-weight:700;padding:4px 10px;border-radius:12px">' + esc(badge) + '</span></div>' : '';
  return '<!doctype html><html lang="de"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="color-scheme" content="light"><title>' + esc(titel) + '</title></head>'
    + '<body style="margin:0;padding:0;background:#f3f4f6;font-family:' + SCHRIFT + '">'
    + '<div style="display:none;max-height:0;overflow:hidden;opacity:0;color:#f3f4f6">' + esc(vorschau || titel) + '</div>'
    + '<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#f3f4f6"><tr><td align="center" style="padding:24px 12px">'
    + '<table role="presentation" width="600" cellpadding="0" cellspacing="0" style="width:100%;max-width:600px;background:#ffffff;border:1px solid #e5e7eb;border-radius:10px;overflow:hidden">'
    + '<tr><td style="background:' + farbe + ';padding:22px 26px"><div style="font-size:12px;font-weight:600;letter-spacing:.1em;text-transform:uppercase;color:#ffffff;opacity:.9">' + esc(label) + '</div>'
    + '<div style="margin-top:6px;font-size:22px;line-height:1.3;font-weight:700;color:#ffffff">' + esc(titel) + '</div>' + plakette + '</td></tr>'
    + '<tr><td style="padding:24px 26px 12px 26px;font-size:15px;line-height:1.6;color:#1f2937">' + abschnitte.join('') + '</td></tr>'
    + '<tr><td style="padding:14px 26px;background:#f9fafb;border-top:1px solid #e5e7eb;font-size:12px;line-height:1.6;color:#6b7280">Automatisch gesendet von n8n am ' + esc(zeit) + ' Uhr<div style="color:#9ca3af">' + ID_ZEILE + '</div></td></tr>'
    + '</table></td></tr></table></body></html>';
};
const e = $('Kurslinks in Entwurf einfügen').item.json;
const t = e.ticket;
const schnitt = e.entwurf.lastIndexOf('\n\nMit freundlichen Grüßen');
const antwort = (schnitt >= 0 ? e.entwurf.slice(0, schnitt) : e.entwurf).trim();
let alsNotiz = false;
try {
  alsNotiz = $('Entwurf als interne Notiz speichern').isExecuted === true;
} catch (fehler) {
  alsNotiz = false;
}
const entwurf = e.modus === 'entwurf' && !alsNotiz;
const art = entwurf ? 'Mail-Entwurf zur Freigabe in Zammad' : 'Interne Notiz in Zammad';
const link = 'https://support-tech.pkr-lab.de/#ticket/zoom/' + t.id;
const zeilen = [
  'Die KI hat Ticket #' + t.number + ' beantwortet.',
  '',
  'Ticket: #' + t.number + ' ' + t.title,
  'Link: ' + link,
  'Ablage: ' + art,
  'Antwort an: ' + (e.replyTo || 'unbekannt'),
  '',
  'Antwort der KI:',
  '',
  antwort,
];
if (e.hinweise.length > 0) {
  zeilen.push('', 'Interne Hinweise:', ...e.hinweise.map((h) => '- ' + h));
}
const abschnitte = [
  felder([['Ticket', '#' + t.number], ['Antwort an', e.replyTo || 'unbekannt'], ['Ablage', art]]),
  knopf('Ticket in Zammad öffnen', link, FARBEN.indigo),
  box(absaetze(antwort), FARBEN.indigo, 'Antwort der KI'),
];
if (e.hinweise.length > 0) abschnitte.push(box(liste(e.hinweise), FARBEN.amber, 'Interne Hinweise'));
const html = layout({
  label: 'Zammad · KI-Antwort',
  farbe: FARBEN.indigo,
  titel: 'Ticket #' + t.number + ': ' + t.title,
  badge: entwurf ? 'Entwurf wartet auf Freigabe' : 'Interne Notiz',
  vorschau: antwort.split('\n')[0],
  abschnitte,
});
return { json: { mailAn: MAIL_AN, mailVon: MAIL_VON, betreff: 'KI-Antwort zu Ticket #' + t.number + ': ' + t.title, text: mitId(zeilen.join('\n')), html } };
